#define main prior_graph_main
#include "graph-check.cpp"
#undef main
#include <obs-module.h>
extern "C" void studio_register_transition_probes(void);
extern "C" const char *obs_module_text(const char *s){return s;}
extern "C" bool obs_module_get_string(const char *s,const char **r){*r=s;return true;}
extern "C" obs_module_t *obs_current_module(void){return nullptr;}
struct Signals {int starts=0,stops=0;obs_source_t *reenter;};
void started(void *v,calldata_t*){auto *s=static_cast<Signals*>(v);++s->starts;obs_source_inc_showing(s->reenter);obs_source_dec_showing(s->reenter);}
void stopped(void *v,calldata_t*){auto *s=static_cast<Signals*>(v);++s->stops;obs_source_inc_showing(s->reenter);obs_source_dec_showing(s->reenter);}
void ticks(std::initializer_list<obs_source_t*> sources){for(auto *s:sources)studio_graph_tick(s);}
int main(int argc,char **argv){if(argc!=2||std::filesystem::exists(argv[1]))return 2;checks=obs_data_array_create();check(obs_startup("en-US",nullptr,nullptr),"Real transition native core startup");obs_source_info i{};i.id="graph_probe";i.type=OBS_SOURCE_TYPE_INPUT;i.output_flags=0;i.get_name=name;i.create=create;i.destroy=destroy;i.show=show;i.hide=hide;i.activate=activate;i.deactivate=deactivate;i.enum_active_sources=enumerate;i.enum_all_sources=enumerate;obs_register_source(&i);studio_register_transition_probes();for(auto *id:{"cut_transition","fade_transition"}){std::string label=std::string(id)+": ";auto *tr=obs_source_create_private(id,"real transition under test",nullptr);auto *dest=obs_source_create_private(id,"real swap destination",nullptr);auto *a=source("transition A"),*b=source("transition B"),*c=source("transition C");check(tr&&dest&&obs_obj_get_data(tr)&&obs_obj_get_data(dest),label+"actual core transition objects created");check(obs_transition_fixed(tr)==(std::string(id)=="cut_transition"),label+"native Cut fixed-duration factory or Fade shader sentinel distinguished");Signals sig{0,0,c};signal_handler_connect(obs_source_get_signal_handler(tr),"transition_start",started,&sig);signal_handler_connect(obs_source_get_signal_handler(tr),"transition_stop",stopped,&sig);
 obs_transition_set(tr,a);count(a,0,0,label+"inactive set creates edge without credit");obs_source_inc_active(tr);ticks({a,b,c,tr});count(a,1,1,label+"MAIN activation reaches sourceA");check(node(a)->shown==1&&node(a)->activated==1,label+"sourceA tick emits show/activate");check(obs_transition_start(tr,OBS_TRANSITION_MODE_AUTO,300,b),label+"real core start A toB");ticks({a,b,c,tr});count(a,1,1,label+"start preserves sourceA credit");count(b,1,1,label+"start adds exact sourceB credit");check(sig.starts==1&&studio_graph_show(c)==0,label+"transition_start callback reenters graph outside gate");check(!obs_transition_start(tr,OBS_TRANSITION_MODE_AUTO,300,b),label+"same active destination folds to current source");ticks({a,b,c,tr});count(a,0,0,label+"folded destination retires sourceA");count(b,1,1,label+"folded destination keeps single sourceB");obs_transition_set(tr,c);ticks({a,b,c,tr});count(b,0,0,label+"set replacement retires sourceB");count(c,1,1,label+"set replacement activates sourceC");obs_transition_clear(tr);ticks({a,b,c,tr});count(c,0,0,label+"clear returns sourceC credit");
 obs_source_inc_showing(tr);obs_transition_set(tr,a);check(obs_transition_start(tr,OBS_TRANSITION_MODE_AUTO,300,b),label+"start with MAIN plusAUX root");ticks({a,b,c,tr});count(a,2,1,label+"A gets MAIN plusAUX");count(b,2,1,label+"B gets MAIN plusAUX");obs_transition_set(dest,c);obs_source_inc_showing(dest);ticks({a,b,c,dest});count(c,1,0,label+"swap destination starts with AUX-onlyC");obs_transition_swap_begin(dest,tr);count(c,0,0,label+"swap begin retires old destinationC");count(a,3,1,label+"swap begin copies active edgeA");count(b,3,1,label+"swap begin copies active edgeB");obs_transition_swap_end(dest,tr);ticks({a,b,c,tr,dest});count(a,1,0,label+"swap end source clear leaves destination AUX-onlyA");count(b,1,0,label+"swap end source clear leaves destination AUX-onlyB");obs_transition_force_stop(tr);check(sig.stops>0&&studio_graph_show(c)==0,label+"stop callback reenters graph outside gate");obs_transition_clear(dest);obs_source_dec_active(tr);obs_source_dec_showing(tr);obs_source_dec_showing(dest);ticks({a,b,c,tr,dest});count(a,0,0,label+"final A credits zero");count(b,0,0,label+"final B credits zero");count(c,0,0,label+"final C credits zero");bool paired=true;for(auto *s:{a,b,c}){auto *n=node(s);paired &= n->shown==n->hidden&&n->activated==n->deactivated;}check(paired,label+"source tick delivery show/hide and activate/deactivate symmetric");signal_handler_disconnect(obs_source_get_signal_handler(tr),"transition_start",started,&sig);signal_handler_disconnect(obs_source_get_signal_handler(tr),"transition_stop",stopped,&sig);obs_source_release(tr);obs_source_release(dest);obs_source_release(a);obs_source_release(b);obs_source_release(c);studio_graph_drain();}
 check(destroyed==6,"All transition leaf sources destroyed after ownership cleanup");obs_shutdown();auto *r=obs_data_create();obs_data_set_array(r,"checks",checks);obs_data_set_int(r,"failures",failures);obs_data_set_bool(r,"passed",!failures);obs_data_set_string(r,"scope","Real core transition init/start/set/clear/swap and Cut plugin factory; real Fade TU with shader-only sentinel factory. No GPU rendering, shader/visual transition, PCM crossfade, Stinger or media-file validation.");obs_data_save_json_safe(r,argv[1],"tmp",nullptr);obs_data_release(r);obs_data_array_release(checks);return failures?1:0;}
